[entities]
// The door back down into the castle, and the shrine in Herran's study.
X = exit map=herrans_castle at=17,8,0 label=Return_to_the_castle model=spire_door yaw=-90
B = save_statue
// Herran's door, and Herran in his observatory, by his telescope under the broken dome.
D = door boss=herran_dead on=P
Y = herran
T = telescope
Z = observatory_dome radius=5 height=1.1
// His study: a chest, his operating table, a shelf of his brews and a bench; his last journal page.
C = chest item=red_tonic count=3 gold=300 model=banded
R = surgery_table
S = potion_shelf
Q = alembic_bench
À = hint text="I am Mother's now: eight hands, palms up.|Let Ilvane keep her moon. The sun keeps me."
// The hatchery's vats and jars, and what crawled out of them.
V = vat
J = specimen_jar
M = vat_spawn
N = drake_magus
// Gaslight in the hall, and light down the stairs.
L = gas_lamp
I = light y=3 color=1.2,0.85,0.5 radius=8
